import{_ as t,o,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Prices and costs","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/03.preise-und-kosten.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/preise-und-kosten.md","filePath":"adapter/sourceanalytix/anleitungen/preise-und-kosten.md","lastUpdated":null}'),r={name:"adapter/sourceanalytix/anleitungen/preise-und-kosten.md"};function n(s,e,c,h,d,l){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="prices-and-costs" tabindex="-1">Prices and costs <a class="header-anchor" href="#prices-and-costs" aria-label="Permalink to &quot;Prices and costs&quot;">​</a></h1><p><a id="costs-recalculated-change-price-change"></a></p><h2 id="are-calculated-costs-recalculated-when-i-change-the-price-and-how-do-i-change-it-from-a-certain-date" tabindex="-1">Are calculated costs recalculated when I change the price, and how do I change it from a certain date? <a class="header-anchor" href="#are-calculated-costs-recalculated-when-i-change-the-price-and-how-do-i-change-it-from-a-certain-date" aria-label="Permalink to &quot;Are calculated costs recalculated when I change the price, and how do I change it from a certain date?&quot;">​</a></h2><p><strong>In short:</strong> Not automatically. A new price applies from the date under &quot;Valid from&quot;, and costs that are already booked stay as they are. From v0.7.0, you can recalculate them afterwards with the &quot;Recalculate costs from date&quot; action.</p><p>SourceAnalytix books costs continuously. With every new value from the source, it multiplies the consumption since the last value by the price that applied during that time and adds the result to the costs of day, week, month, quarter and year. It remembers each price together with its start time in the state <code>sourceanalytix.0.priceHistory.&lt;category&gt;</code>. That is why a new price doesn&#39;t change costs that are already booked.</p><h3 id="change-the-price-from-a-certain-date-from-v0-7-0" tabindex="-1">Change the price from a certain date (from v0.7.0) <a class="header-anchor" href="#change-the-price-from-a-certain-date-from-v0-7-0" aria-label="Permalink to &quot;Change the price from a certain date (from v0.7.0)&quot;">​</a></h3><ol><li>Open the instance settings of SourceAnalytix and go to the &quot;Price definitions&quot; tab.</li><li>In the row of your tariff, enter the new price under &quot;Price per unit&quot; and the date it applies from under &quot;Valid from&quot;. The date can be in the future.</li><li>Save. The adapter restarts.</li><li>Until that date, SourceAnalytix calculates with the old price, and from 0:00 on that date with the new one. At the day rollover, <code>sourceanalytix.0.priceDefinitions.&lt;category&gt;.currentPrice</code> also shows the new price, and the log says &quot;Unit price for … changed from … to … (valid from date reached)&quot;.</li></ol><p>&quot;Valid from&quot; works the same way for &quot;Price per month&quot;. If you switch providers, enter the new price in the same price definition. That keeps the price history together, and you don&#39;t change anything on the sources.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>With every price change, also enter a new date under &quot;Valid from&quot;. If you leave the date of the last change, the new price replaces the old one in the price history from that date. A date before the last price change only takes effect up to that change, and after it the later price applies again. If &quot;Valid from&quot; is empty, the new price applies from the moment you save.</p><p><strong>From v0.7.0</strong>, the dialog marks &quot;Price per unit&quot;, &quot;Price per month&quot; and &quot;Valid from&quot; in red and shows &quot;Price changed but &quot;Valid from&quot; did not …&quot; as soon as you change a price without adjusting the date. You can still save, in case you are only fixing a typo. After saving, a warning also appears in the log. If you replaced the old price by mistake: enter the old price again and save, then enter the new price with its own &quot;Valid from&quot; date and save.</p></div><h3 id="recalculate-costs-that-are-already-booked-from-v0-7-0" tabindex="-1">Recalculate costs that are already booked (from v0.7.0) <a class="header-anchor" href="#recalculate-costs-that-are-already-booked-from-v0-7-0" aria-label="Permalink to &quot;Recalculate costs that are already booked (from v0.7.0)&quot;">​</a></h3><p>If a price applied earlier than the date you entered it, set the correct date under &quot;Valid from&quot; and save. Then open the source on the &quot;Overview&quot; tab and choose the &quot;Recalculate costs from date&quot; action with the same date. The action is only available for sources with &quot;Costs&quot;, and you start it for each source separately. What exactly it does and where its limits are is described under <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Repair costs</a>.</p><p><strong>Up to v0.6.x:</strong> There is no recalculation. Booked costs stay at the old price, even in the current period.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a> · <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">How can I read and set prices as states?</a></p><p><a id="include-monthly-base-fee"></a></p><h2 id="how-do-i-include-a-monthly-basic-fee" tabindex="-1">How do I include a monthly basic fee? <a class="header-anchor" href="#how-do-i-include-a-monthly-basic-fee" aria-label="Permalink to &quot;How do I include a monthly basic fee?&quot;">​</a></h2><p><strong>In short:</strong> Enter the basic fee in the price definition under &quot;Price per month&quot; and switch on &quot;Include basic fee&quot; on the source. &quot;Costs&quot; must also be on for the source. Divide an annual basic fee by 12 first.</p><p>SourceAnalytix books the basic fee as a full monthly amount on the first of each month. In the first month, it books it on the day the price takes effect. That is why the monthly value contains the whole basic fee from the 1st on. Quarter and year contain the sum of their months. Day and week only contain it if the first of the month falls within them.</p><p>An example with a basic fee of €12, valid since January 1, on March 15:</p><table tabindex="0"><thead><tr><th>Period</th><th>Basic fee in it</th></tr></thead><tbody><tr><td>Day, week</td><td>€0</td></tr><tr><td>Month</td><td>€12</td></tr><tr><td>Quarter</td><td>€36</td></tr><tr><td>Year</td><td>€36</td></tr></tbody></table><p>If you enter the basic fee for the first time without &quot;Valid from&quot;, it applies from January 1 of the current year. The annual value then immediately contains all months since January.</p><h3 id="how-to-do-it-from-v0-7-0" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>In the instance settings, on the &quot;Price definitions&quot; tab, enter the &quot;Price per month&quot; for your tariff and save. The adapter restarts.</li><li>For a new source, tick &quot;Include the basic fee of this price definition&quot; in the wizard, in the &quot;Price&quot; step.</li><li>For an existing source, tick &quot;Include basic fee&quot; in its source detail under &quot;Settings&quot; and click &quot;⚡ Apply&quot;.</li><li>Check the state <code>sourceanalytix.0.&lt;device&gt;.currentYear.costs.03_currentMonth</code>. It now contains the basic fee.</li></ol><h3 id="several-sources-with-the-same-price-definition" tabindex="-1">Several sources with the same price definition <a class="header-anchor" href="#several-sources-with-the-same-price-definition" aria-label="Permalink to &quot;Several sources with the same price definition&quot;">​</a></h3><p>Every source with &quot;Include basic fee&quot; books the full basic fee. If several sources belong to one connection, for example your main household supply and a sub-meter, it would otherwise be counted more than once. In that case, switch it on for one source only.</p><p><strong>From v0.7.0</strong>, SourceAnalytix points this out in several places (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1268" target="_blank" rel="noreferrer">#1268</a>):</p><ul><li>The wizard leaves the checkmark off if another source with the same price definition already books the basic fee, and shows &quot;… already books the basic fee of this price definition. If it is on here too, it counts twice.&quot;</li><li>The &quot;Problems&quot; tab shows &quot;Basic fee is booked twice&quot; with the &quot;Switch off here&quot; button.</li><li>At startup, the log says <code>The basic fee of price definition &lt;name&gt; is included by &lt;n&gt; sources … and is counted once per source</code>.</li></ul><p>If each source really has its own connection with its own basic fee, leave the checkmark on for all of them.</p><p>If you change the basic fee, &quot;Valid from&quot; works as it does for the price per unit, see <a href="#costs-recalculated-change-price-change">Change the price from a certain date</a>. The &quot;Recalculate costs from date&quot; action includes the basic fee.</p><p><strong>Up to v0.6.x:</strong> The checkmark is called &quot;Including basic rate&quot; and is in the SourceAnalytix settings of the datapoint under &quot;Calculation settings&quot;.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Costs stay 0</a></p><p><a id="use-dynamic-electricity-price-tibber"></a></p><h2 id="how-do-i-use-a-dynamic-electricity-price-tibber-awattar" tabindex="-1">How do I use a dynamic electricity price (Tibber, Awattar)? <a class="header-anchor" href="#how-do-i-use-a-dynamic-electricity-price-tibber-awattar" aria-label="Permalink to &quot;How do I use a dynamic electricity price (Tibber, Awattar)?&quot;">​</a></h2><p><strong>In short:</strong> In the price definition, set &quot;Price source&quot; to &quot;State value&quot; and choose the datapoint with the current price under &quot;Price state&quot;. SourceAnalytix remembers every price change with its time and values each bit of consumption at the price that applied at that moment.</p><h3 id="how-to-do-it-from-v0-7-0-1" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-1" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>In the instance settings, open the &quot;Price definitions&quot; tab and add a row or change your existing one.</li><li>Under &quot;Price source&quot;, choose &quot;State value&quot;, and under &quot;Price state&quot; the datapoint of your electricity price adapter.</li><li>Save. The adapter restarts and writes <code>Loaded unit price &lt;price&gt; for &lt;category&gt; from &lt;datapoint&gt;</code> to the log.</li><li>Assign the price definition to your sources, see <a href="#assign-prices-create-custom-tariffs">How do I assign prices and create my own tariffs (e.g. heat pump)?</a>.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The datapoint must deliver the price in your currency per unit of the price definition, for example <code>0.28</code> for 28 cents per kWh. SourceAnalytix multiplies the value directly by the consumption. If your adapter delivers cents, convert it first, for example with an alias.</p></div><p>Whenever the datapoint changes, the log says &quot;Unit price for … changed from … to …&quot;. If it has no valid value at startup, SourceAnalytix logs a warning and calculates with the last fixed price you entered, or with 0 if there is none, until the first valid price arrives. It ignores an invalid new value and keeps the current price.</p><h3 id="how-the-costs-are-split" tabindex="-1">How the costs are split <a class="header-anchor" href="#how-the-costs-are-split" aria-label="Permalink to &quot;How the costs are split&quot;">​</a></h3><p>If a price change falls between two values from the source, SourceAnalytix splits the consumption by time. Example: 1 kWh was consumed between 13:50 and 14:10, and at 14:00 the price drops from €0.30 to €0.20. The first half then costs €0.15 and the second €0.10, €0.25 in total. The more often your source sends, the closer this gets to the real consumption.</p><h3 id="where-the-costs-are-stored" tabindex="-1">Where the costs are stored <a class="header-anchor" href="#where-the-costs-are-stored" aria-label="Permalink to &quot;Where the costs are stored&quot;">​</a></h3><ul><li>SourceAnalytix keeps the running costs from day to year in <code>sourceanalytix.0.&lt;device&gt;.dynamicCostMemory</code>. After a restart it carries on from there and doesn&#39;t revalue the consumption so far at the current price.</li><li>All prices with their time are in <code>sourceanalytix.0.priceHistory.&lt;category&gt;</code>.</li><li>The current price is shown in <code>sourceanalytix.0.priceDefinitions.&lt;category&gt;.currentPrice</code>.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>&quot;Recalculate costs from date&quot; only knows the consumption per period and spreads it evenly over the period. For a price that changes hourly, the result is only an approximation and is usually less accurate than the costs booked as you go. With dynamic prices, only use the action to fix an error.</p></div><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">How can I read and set prices as states?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Values or costs far too high</a></p><p><a id="bill-day-night-tariff"></a></p><h2 id="how-do-i-bill-a-day-night-tariff-high-low-rate" tabindex="-1">How do I bill a day/night tariff (high/low rate)? <a class="header-anchor" href="#how-do-i-bill-a-day-night-tariff-high-low-rate" aria-label="Permalink to &quot;How do I bill a day/night tariff (high/low rate)?&quot;">​</a></h2><p><strong>In short:</strong> In the price definition, set &quot;Price source&quot; to &quot;Tariff selector&quot;. A datapoint then switches between two prices, and SourceAnalytix values the consumption of your single meter at the price that currently applies. It doesn&#39;t split the consumption itself into high and low rate.</p><h3 id="how-to-do-it-from-v0-7-0-2" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-2" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Provide a switch datapoint that is, for example, <code>true</code> during one tariff and <code>false</code> otherwise. SourceAnalytix doesn&#39;t know the times of day. A script or a schedule, for example, sets the datapoint.</li><li>In the instance settings, on the &quot;Price definitions&quot; tab, choose &quot;Tariff selector&quot; under &quot;Price source&quot;.</li><li>Under &quot;Price per unit&quot;, enter the price that applies when the switch datapoint is not active, and under &quot;Active tariff price&quot; the price for the active state.</li><li>Under &quot;Price state&quot;, choose the switch datapoint.</li><li>Save. The adapter restarts.</li></ol><p>When the datapoint counts as active:</p><table tabindex="0"><thead><tr><th>&quot;Active selector value&quot;</th><th>Active when the datapoint …</th></tr></thead><tbody><tr><td>entered</td><td>has exactly this value, for example <code>NT</code> or <code>2</code></td></tr><tr><td>empty</td><td>is <code>true</code>, a number other than 0, or a text other than <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code>, <code>closed</code> and empty</td></tr></tbody></table><p>Every switch is recorded in the price history with its time, and the log says &quot;Unit price for … changed from … to …&quot;. If a switch falls between two values from the source, SourceAnalytix splits the consumption by time, as described under <a href="#use-dynamic-electricity-price-tibber">dynamic electricity price</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If your meter provides separate meter readings for high and low rate, you can create both as separate sources instead, each with a price definition with a fixed price. Then you also get the consumption per tariff.</p></div><p>Showing the consumption per tariff from a single meter is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1273" target="_blank" rel="noreferrer">#1273</a>).</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a></p><p><a id="assign-prices-create-custom-tariffs"></a></p><h2 id="how-do-i-assign-prices-and-create-my-own-tariffs-e-g-heat-pump" tabindex="-1">How do I assign prices and create my own tariffs (e.g. heat pump)? <a class="header-anchor" href="#how-do-i-assign-prices-and-create-my-own-tariffs-e-g-heat-pump" aria-label="Permalink to &quot;How do I assign prices and create my own tariffs (e.g. heat pump)?&quot;">​</a></h2><p><strong>In short:</strong> There is no default price. Every source has exactly one price definition. For your own tariff, for example for the heat pump, add another row on the &quot;Price definitions&quot; tab and select it on the source.</p><h3 id="how-to-do-it-from-v0-7-0-3" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-3" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>In the instance settings, open the &quot;Price definitions&quot; tab and add a row.</li><li>Under &quot;Category&quot;, enter a unique name, for example <code>Waermepumpe</code>. You use this name later to select the tariff.</li><li>Choose the &quot;Cost Type&quot; (&quot;Costs&quot; for consumption from the grid, &quot;Earnings&quot; for feed-in), the &quot;Unit&quot; you want to calculate in, the &quot;Price source&quot; and the &quot;Price per unit&quot;, and if needed the &quot;Price per month&quot;.</li><li>Save. The adapter restarts.</li><li>For a new source, choose the tariff in the wizard in the &quot;Price&quot; step. Only price definitions whose unit matches the source can be selected.</li><li>For an existing source, choose it in the source detail under &quot;Settings&quot; in &quot;Price definition&quot; and click &quot;⚡ Apply&quot;.</li></ol><p>Several sources may use the same price definition. If it books a basic fee, read <a href="#include-monthly-base-fee">Several sources with the same price definition</a>. All fields of the table are explained under <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a>.</p><h3 id="costs-per-kilometer-or-in-a-custom-unit" tabindex="-1">Costs per kilometer or in a custom unit <a class="header-anchor" href="#costs-per-kilometer-or-in-a-custom-unit" aria-label="Permalink to &quot;Costs per kilometer or in a custom unit&quot;">​</a></h3><p>The price always applies per unit of the price definition. For costs per kilometer, choose the unit <code>km</code> and a source that delivers an odometer reading in <code>km</code> or <code>m</code>. From v0.7.0, there is the unit <code>piece</code> for a price per piece. Which units are available is listed under <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported (energy, volume, weight, length)?</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Don&#39;t rename a category while sources use it. The sources then can&#39;t find their price definition and stop calculating. The log says <code>Selected Type &lt;name&gt; does not exist in Price Definitions</code>, and the &quot;Problems&quot; tab shows &quot;Price definition no longer exists&quot;. The price history is also tied to the old name. After a rename, choose the new price definition on every source.</p></div><p><strong>Up to v0.6.x:</strong> The table of price definitions is also in the instance settings. You assign them on the datapoint under &quot;Select price definition&quot;, see <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a>.</p><p><strong>See also:</strong> <a href="./quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)?</a> · <a href="./quellen-und-einheiten#track-pv-yield-feed-earnings">How do I track PV yield, feed-in and earnings?</a></p>',65)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
